 "问数答案组合容器：快照渲染，认证徽章、正文角标、结果表、图表各槽有才渲。": "Ask-data answer container: snapshot rendering—the badge, in-text citation markers, result table, and chart slots each render only when present.",
 "澄清反问卡：选项 chips 点选作答，答后锁定并回显解析结果。": "Clarifying-question card: answer by picking option chips; the answer locks in and the resolved result is echoed back.",
 "口径解释折叠面板：拆解数字的表 / 列 / 筛选 / 聚合与指标口径。": "Metric-definition accordion: unpacks the table / column / filter / aggregation behind a number and its metric definition.",
 "RAG/LLM 调用链 span 树，覆盖查询、检索、重排、生成、工具等节点的嵌套耗时展示。": "RAG/LLM trace span tree: nested timing across nodes such as query, retrieval, reranking, generation, and tools.",
 "人工标注审查队列，左侧队列加右侧审查卡，支持选项打分与数值滑杆。": "Human annotation review queue: queue on the left, review card on the right, with option scoring and numeric sliders.",
 "无答案 / 未命中查询分析，含趋势柱与零结果 Top 表。": "No-answer / zero-hit query analytics, with trend bars and a top zero-results table.",
 "评估 run 对比表（Braintrust 心智），覆盖判级汇总、指标对比与双栏 diff。": "Evaluation run comparison table (Braintrust mental model): grading summary, metric comparison, and a two-column diff.",
 "Agent 双栏工作台画布，覆盖对话流、文档栏、内联 diff、版本轴与划词 AI 工具条。": "Agent split-canvas workbench: conversation stream, document pane, inline diff, version axis, and a select-text AI toolbar.",
 "Agent 检查点时间轴，点击弹出恢复菜单按范围回滚。": "Agent checkpoint timeline: click to open a restore menu and roll back by scope.",
 "MCP App 沙箱工具容器（MCP Apps 对齐），iframe 隔离加 JSON-RPC 双向桥。": "MCP App sandbox tool container (aligned with MCP Apps): iframe isolation plus a two-way JSON-RPC bridge.",
 "Agent 工具链条横向摘要条，一屏看完检索到引用核对的整链状态。": "A horizontal Agent tool-chain summary strip: the whole chain's status from retrieval to citation checking in one glance.",
 "SharePoint 权限页范式的资源级 ACL 面板，覆盖继承、授权行、链接与过度授权警示。": "Resource-level ACL panel modeled on the SharePoint permissions page: inheritance, grant rows, links, and over-permission warnings.",
 "SharePoint「Check Permissions」范式的 view-as 检查器，结论加扁平原因链。": "View-as checker modeled on SharePoint “Check Permissions”: a conclusion plus a flat chain of reasons.",
 "Google Drive「请求访问」范式的访问申请流，含被拒页、申请表单与状态机徽章。": "Access request flow modeled on Google Drive “Request access”: a denied page, request form, and state-machine badges.",
 "Purview / Box 范式的权限审计时间线，含通道过滤、权限异味与 break-glass 警示。": "Permission audit timeline modeled on Purview / Box: channel filters, permission smells, and break-glass warnings.",
 "admin / 审计专用的检索可见性对照器：固定身份集 × 同一查询的命中对照网格。": "A retrieval visibility comparer for admins and auditors: a grid comparing hits for a fixed set of identities × the same query.",
 "单行与多行输入的外壳族：前后缀、清除钮、密码切换、计数与掩码。": "The shell family for single- and multi-line input: prefix/suffix, clear button, password toggle, counter, and masking.",
 "数值滑块：单值与双值区间两种形态，样式自由、键盘可达。": "Numeric slider: single-value and range forms, style-agnostic and keyboard accessible.",
 "开关、勾选框、单选行组三件套：纯 CSS 状态组件。": "Switch, checkbox, and radio-row trio: pure CSS state components.",
 "四件紧凑小控件：分段选择、切换组、数字步进器、验证码格。": "Four compact controls: segmented control, toggle group, number stepper, and verification-code grid.",
 "文件上传：点击或拖拽入区，自动渲染文件列表与校验错误。": "File upload: click or drag files in; the file list and validation errors render automatically.",
 "媒体卡：2/3 封面 + 悬停上浮与底部信息条。": "Media card: a 2/3 cover with hover lift and a bottom info bar.",
 "评分：实星 / 半星两档精度，warning 色。": "Rating: full-star / half-star precision, in warning color.",
 "键帽与行内代码片：键盘按键和行内代码的排版件。": "Keycaps and inline code chips: typographic pieces for keyboard keys and inline code.",
 "分隔列表：行间细分隔线 + 悬停底色的纵向条目。": "Divided list: vertical entries with hairline separators and a hover background.",
 "时间线：语义色圆点 + 连接线，时间右对齐等宽数字。": "Timeline: semantic-color dots + connecting lines, with right-aligned tabular numerals for times.",
 "树形列表：多层可折叠、叶子单选、禁用节点。": "Tree list: multi-level collapsible, single-select leaves, and disabled nodes.",
 "显式滚动区：给「可滚动」一个看得见的边界。": "Explicit scroll area: gives “scrollable” a visible boundary.",
 "基础表格：窄屏横向滚动、行悬停、斑马纹与首列粘滞。": "Basic table: horizontal scrolling on narrow screens, row hover, zebra stripes, and a sticky first column.",
 "操作终态的全幅展示：成功、失败、警告、信息四种收场。": "Full-page display of operation outcomes: success, failure, warning, and info endings.",
 "旋转加载指示：sm / 默认 / lg 三档。": "Spinner: sm / default / lg sizes.",
 "加载占位：呼吸脉冲的灰块，拼出内容轮廓。": "Loading placeholder: pulsing gray blocks that piece together the shape of the content.",
 "站点顶部导航：左中右三段玻璃栏，滚动时自动收边。": "Site top navigation: a three-section glass bar that automatically trims its edges on scroll.",
 "分组可折叠的侧栏导航：条目带图标与当前态。": "Grouped, collapsible sidebar navigation: items with icons and current state.",
 "分页页码条：纯样式契约，含当前页、禁用与省略号。": "Pagination bar: a styles-only contract, with current page, disabled, and ellipsis states.",
 "步骤条：多阶段流程的进度导航，横向与垂直同一 DOM。": "Stepper: progress navigation for multi-stage flows; horizontal and vertical share the same DOM.",
 "零 JS 的布局工具类全集：堆叠、网格、容器、宽高比与可读性件。": "The full set of zero-JS layout utilities: stack, grid, container, aspect-ratio, and readability helpers.",
