 "什么是 @icen.ai/ui？": "What is @icen.ai/ui?",
 "icen.ai 生态的统一设计系统：设计 tokens + 无框架组件 CSS + 行为 JS，所有前端从这里取设计资产。": "The unified design system of the icen.ai ecosystem: design tokens + framework-agnostic component CSS + behavior JS. Every frontend sources its design assets from here.",
 "如何切换色彩预设？": "How do I switch color presets?",
 "预设类挂在 html 上：modern 现代（默认）/ dongyun 东韵 / jugou 巨构 / piano 钢琴 / monet 莫奈 / vangogh 梵高；明暗用 data-icen-theme，原语用 data-icen-style=\"modern|chinese|soviet|pixel\"，两轴独立。": "Preset classes go on html: modern (default) / dongyun / jugou / piano / monet / vangogh; color mode via data-icen-theme, primitives via data-icen-style=\"modern|chinese|soviet|pixel\"—the two axes are independent.",
 "组件可以直接写死颜色吗？": "Can components hardcode colors directly?",
 "不可以。组件 CSS 只消费 --icen-token-* 变量，语义色仅绿 / 黄 / 红 + 品牌 accent 四档。": "No. Component CSS only consumes --icen-token-* variables; semantic color has just four levels: green / yellow / red plus the brand accent.",
