 "文档操作区域": "Document actions area",
 "右键菜单 · 组件 · ICEN UI": "Context menu · Components · ICEN UI",
 "在当前位置展开相关操作。支持右键、触屏长按和键盘，关闭后回到原来的焦点。": "Relevant actions open right where you are. Right-click, touch long-press, and keyboard all work, and focus returns to where it started on close.",
 "右键打开文档操作；也可以聚焦后按 Shift + F10，或在触屏上长按。": "Right-click for document actions; or focus it and press Shift + F10, or long-press on a touch screen.",
 "区域外右键则是默认菜单：后退 / 前进 / 刷新 / 复制页面链接。": "Right-clicking outside the area gets the default menu: Back / Forward / Reload / Copy page link.",
 "注册": "Registration",
 "：  注册；元素挂   即命中": ":  registers it; any element carrying   is picked up",
 "：支持 header / separator / danger / disabled": ": supports header / separator / danger / disabled",
 "触屏": "Touch",
 "：长按触发": ": triggered by a long press",
 "：全局同时只存在一个菜单": ": only one menu exists globally at a time",
 "上一个：骨架屏": "Previous: Skeleton",
 "下一个：通知栈": "Next: Notifications",
 "复制按钮 · 组件 · ICEN UI": "Copy button · Components · ICEN UI",
 "复制一条命令或一个链接，等待、完成与重试都留在原处。": "Copy a command or a link — waiting, done, and retry all happen right where you are.",
 "复制作品链接": "Copy artwork link",
 "暂不可用": "Unavailable",
 "先模拟一次失败，再尝试真实复制。等待时可以继续阅读，重复点击不会重复执行。": "A failure is simulated first, then a real copy is attempted. You can keep reading while it waits, and repeated clicks never run twice.",
 "复制分享地址": "Copy share link",
 "选择一项，复制后会在这里确认。": "Pick one — the copy confirmation shows up here.",
 "：文本钮 / 透明钮 / 图标钮，三档尺寸共用同一行为": ": text / ghost / icon buttons — one behavior across three sizes",
 "：等待与完成不改变按钮宽度，原始插槽节点始终保留；失败显示可读提示，点原按钮即可重试": ": waiting and done never change the button's width, and the original slot nodes are always preserved; a failure shows a readable message and clicking the same button retries",
 "quiet 变体": "quiet variant",
 "：上下文内随悬停或焦点显现，触屏常显": ": appears on hover or focus within the context, always visible on touch",
 "剪贴板": "Clipboard",
 "：默认系统剪贴板 + 兼容回退；可传   接入原生桥或权限流程": ": system clipboard by default with a compatibility fallback; pass   to wire in a native bridge or a permission flow",
 "上一个：表格": "Previous: Table",
 "下一个：顶栏": "Next: Top navigation",
 "数据表格 · 组件 · ICEN UI": "Data table · Components · ICEN UI",
 "多列排序 + 列重排：Shift+点击表头追加次级排序（徽标 = 优先级序号）；拖表头换位（影子 + 插入指示线），完成派 icen:table-column-reorder": "Multi-column sort + column reorder: Shift+click a header to add a secondary sort (the badge = the priority order); drag headers to move them (drag ghost + drop indicator), firing icen:table-column-reorder when done",
 "行分组 + 聚合：按部门分组（组名 + 计数 + 聚合 chip），点击组头折叠派 icen:table-group-toggle，状态跨 setData 保持": "Row grouping + aggregation: grouped by department (group name + count + aggregate chip); clicking a group header collapses it and fires icen:table-group-toggle, with the state surviving setData",
 "单元格编辑：双击或 Enter 进入编辑——金额列数字校验（非法值抖动不提交），状态列下拉选择；提交派 icen:table-cell-edit，宿主调 updateCell 采纳": "Cell editing: double-click or Enter to edit — the amount column validates numbers (invalid values shake and aren't committed), the status column is a dropdown; commits fire icen:table-cell-edit, and the host applies them via updateCell",
 "右冻结 + 汇总行：操作列右固定（sticky 偏移按列宽累计）；表尾合计行钉住不滚动，按筛选后数据实时重算": "Right pinning + summary row: the actions column is pinned right (sticky offsets accumulate by column width); the footer totals row stays pinned without scrolling and recalculates live from the filtered data",
 "汇总行：summaryRow 逐列规格（sum/avg/count/min/max/label），true = 复用列 aggregate": "Summary row: summaryRow takes a per-column spec (sum/avg/count/min/max/label); true reuses the column's aggregate",
 "键盘导航 + 复制：方向键移动焦点格（Home/End 行首末、PageUp/Down 翻屏跨页），Ctrl/Cmd+C 复制当前格或选中行集（TSV）": "Keyboard navigation + copy: arrow keys move the focused cell (Home/End for row ends, PageUp/Down to page through), Ctrl/Cmd+C copies the current cell or the selected rows (TSV)",
 "：单列 / 多列排序——Shift+点击追加次级，徽标显示优先级": ": single- / multi-column sort — Shift+click appends secondary sorts, badges show priority",
 "列": "Columns",
