 "界面图标 · 组件 · ICEN UI": "Interface icons · Components · ICEN UI",
 "同一个图形在不同字号下保持对齐。": "The same glyph stays aligned at every font size.",
 "次要动作保留固定槽位。悬停这一行，或按 Tab 聚焦，移除按钮显现；内容不会位移。": "Secondary actions keep a fixed slot. Hover this row, or focus it with Tab, and the remove button appears; nothing shifts.",
 "产品设计规范": "Product design guidelines",
 "规范已移除。": "Guideline removed.",
 "撤销": "Undo",
 "：固定 20px 光学网格，统一线宽与端点，不同字号保持对齐": ": a fixed 20px optical grid, uniform stroke weight and endpoints, aligned across font sizes",
 "：  服务端 HTML（全转义）；  原生 DOM，无字体依赖": ":  server-side HTML (fully escaped);  native DOM, no font dependency",
 "：带   自动  ；在已有名称的按钮中默认": ": with   present,   kicks in automatically; default in buttons that already have a name",
 "：  注册自有图形走同一网格；只接受 SVG path，不执行脚本": ":  register your own glyphs on the same grid; only SVG paths accepted, no script execution",
 "次要动作": "Secondary actions",
 "：  +   悬停 / 聚焦显现，触屏常显": ":  +   appear on hover / focus, always visible on touch",
 "次要动作槽位固定、显现不位移；只用于次要操作，不要隐藏主要操作或关键状态。": "Secondary-action slots are fixed and revealing them shifts nothing; use them for secondary operations only—never hide primary actions or critical states.",
 "方向图标的 RTL 语义由所在组件决定，通用图标不会擅自翻转。": "The RTL semantics of directional icons belong to the host component; general-purpose icons never flip on their own.",
 "129 个无框架组件，9 个分组。全部消费同一套设计令牌——切换右上角的预设、明暗与风格，每张卡片即刻换装。": "129 framework-agnostic components across 9 groups, all powered by the same design tokens. Change the preset, color mode, or style above to restyle every component.",
 "分区内容导航：滑动墨水条、完整键盘契约，激活态可同步地址栏。": "Sectioned content navigation: a sliding ink bar, a complete keyboard contract, and an active state that can sync to the address bar.",
 "瞬时轻提示：角落滑入、自动消散，success / error / warn / info 四态语义色。": "Ephemeral toasts: slide in from a corner and fade away on their own, with semantic colors for all four states—success / error / warn / info.",
 "自定义下拉选择：单选、可搜索、多选上限，选项可放任意内容。": "Custom select dropdowns: single choice, searchable, multi-select limits, and options that can hold any content.",
 "把零散词句收成标签的输入控件：回车、逗号或粘贴成词条，重复与超限有明确反馈。": "An input that gathers scattered words into tags: Enter, comma, or paste creates entries, with clear feedback for duplicates and limit overruns.",
 "日历选日期：单选、范围、禁用与清除，键盘可全程操作。": "Calendar date picking: single date or range, disable and clear, fully operable from the keyboard.",
 "路径型级联选择：多级面板逐级展开，支持跨级搜索与完整键盘操作。": "Path-style cascading selection: multi-level panels unfold level by level, with cross-level search and full keyboard support.",
 "层级树选择：组织架构 / 权限树的单选或多选，父子联动、搜索与已选 chips。": "Hierarchical tree selection: single or multiple choice for org charts / permission trees, parent-child linking, search, and selected chips.",
 "提及输入：@ 触发成员建议；提及渲染为原子 token（光标不可进入、整体删除），目录与自定义两种模式，数据是对象数组而非字符串猜测。": "Mentions input: @ triggers member suggestions; mentions render as atomic tokens (the caret can't enter them, and they delete as a whole), in directory or custom mode, backed by an array of objects rather than guessed strings.",
 "自动补全：输入联想同步或异步建议，支持自由输入、自定义行与失败原地重试。": "Autocomplete: typing pulls sync or async suggestions, with free-form input, custom rows, and in-place retry on failure.",
 "代码块：高亮、行号、折叠、复制与 diff 着色，浏览器与构建期双入口。": "Code blocks: highlighting, line numbers, folding, copy, and diff coloring, with both browser and build-time entry points.",
 "轮播：箭头、圆点、滑动、键盘四条通道同一个切换引擎。": "Carousel: arrows, dots, swipe, and keyboard—four channels, one switching engine.",
 "模态对话框与四向贴边 Sheet：焦点陷阱、滚动锁、Esc 关闭一应俱全。": "Modal dialogs and four-way edge-docked Sheets: focus trap, scroll lock, and Esc-to-close all built in.",
 "触发器下方的下拉菜单：模板声明，自动定位与翻转。": "Dropdown menus below their triggers: declared in templates, with automatic positioning and flipping.",
 "右键菜单：全局单例注册，触屏长按同样唤起。": "Context menus: registered as a global singleton; a touch long-press opens them too.",
 "声明式弹出层：点击开合、智能选侧、焦点归还。": "Declarative popovers: click to toggle, smart side selection, focus returned on close.",
 "声明式气泡提示：属性写文案，悬停与聚焦自动浮现。": "Declarative tooltips: write the copy as an attribute; they appear automatically on hover and focus.",
 "线性进度条：轨道 + 填充 + 等宽数字标签，宽度变化平滑过渡。": "Linear progress bars: track + fill + tabular-number labels, with smooth width transitions.",
 "一键复制：文本、透明、图标三种按钮形态共用同一复制行为。": "One-click copy: text, ghost, and icon button styles share the same copy behavior.",
 "工程级持久通知栈：进度、多按钮、已读未读、localStorage 持久化。": "Engineering-grade persistent notification stacks: progress, multiple buttons, read and unread, persisted to localStorage.",
