 "知识库总览 · 组件 · ICEN UI": "Knowledge-base overview · Components · ICEN UI",
 [`ai 族描述思考，kb 族呈现证据。${META.kb.domains} 域 ${META.kb.components} 个组件，共享数据契约 kb-core（类型 + 纯函数 + 来源类型注册表）与视觉基座 kb.css——数字一律等宽、引文一律引用体、来源 / 分数 / 日期只用语义色。`]: `The ai family narrates the thinking; the kb family presents the evidence. ${META.kb.components} components across ${META.kb.domains} domains share the kb-core data contract (types + pure functions + a source-type registry) and the kb.css visual foundation — numbers are always tabular, quotes always in quotation style, and sources / scores / dates use semantic colors only.`,
 "证据域 · ground": "Evidence domain · ground",
 "引用是主角": "Citations front and center",
 "答案的证据链：行内引用角标（hover 引用卡）、来源列表、原文定位抽屉、来源冲突对勘（市场空白组件）。": "An answer's evidence chain: inline citation markers (hover for the citation card), a source list, a source-passage drawer, and side-by-side source-conflict comparison (a market-gap component).",
 "摄取域 · ingest": "Ingestion domain · ingest",
 "解析先行": "Parse first",
 "进知识库之前：解析管线时间线、chunk 编辑器、分段策略实时预览、连接器健康、元数据、认证 QA 对。": "Before content enters the knowledge base: a parsing-pipeline timeline, a chunk editor, live chunking-strategy previews, connector health, metadata, and vetted Q&A pairs.",
 "检索域 · search": "Retrieval domain · search",
 "可解释分数": "Explainable scores",
 "检索 playground（topK / 混合权重 / rerank）、过滤器构建器（Mongo / OData 双序列化）、rerank A/B 对比、召回测试集。": "A retrieval playground (topK / hybrid weights / rerank), a filter builder (dual Mongo / OData serialization), rerank A/B comparisons, and recall test sets.",
 "问数域 · data": "Ask-data domain · data",
 "认证优先于生成": "Certify before generating",
 "生成 SQL 卡（可见性 / 修正 diff）、问数答案容器、澄清反问、口径解释面板。": "A generated-SQL card (visibility / correction diff), an ask-data answer container, clarifying questions, and a metric-definition panel.",
 "治理域 · ops": "Governance domain · ops",
 "观测与标注": "Observability and review",
 "trace span 树、标注队列（全键盘流）、无答案分析（建文档 / 加同义词）、评估对比（判级徽章）。": "A trace span tree, a review queue (fully keyboard-driven), no-answer analysis (write a doc / add synonyms), and evaluation comparisons (grade badges included).",
 "工作台域 · agent": "Workspace domain · agent",
 "动效非颜色": "Motion, not color",
 "双栏画布（划词 AI 操作）、检查点（只回滚内容保留对话）、沙箱容器（postMessage JSON-RPC）、工具链条。": "A split canvas (text-selection AI actions), checkpoints (roll back the content, keep the conversation), a sandbox container (postMessage JSON-RPC), and the tool chain.",
 "：呈现证据（知识从哪来、可信吗、怎么用），与 ai 族互补": ": presents evidence (where the knowledge comes from, whether it can be trusted, and how to use it), complementing the ai family",
 "：契约与纯函数统一在  （类型 + 来源类型注册表）": ": contracts and pure functions unified in  (types + source-type registry)",
 "：视觉基座  （等宽数字 / 引用体 / 徽标）": ": the visual foundation  (tabular numbers / quotation style / badges)",
 "分域": "By domain",
 [`：${META.kb.domains} 域 ${META.kb.components} 个组件，各持一份合并 CSS`]: `: ${META.kb.components} components across ${META.kb.domains} domains, each with its own merged CSS`,
 "：  一行装全家，细分 slug 可独立安装": ":  brings in the whole family in one line; fine-grained slugs can be installed individually",
 "数字一律   等宽、引文一律   引用体、来源 / 分数 / 日期只用语义色。": "Numbers are always   tabular, quotes always   in quotation style, and sources / scores / dates use semantic colors only.",
