 "访问申请流 · 组件 · ICEN UI": "Access request flow · Components · ICEN UI",
 "推进状态机 →": "Advance state machine →",
 "你没有访问权限——「不知道」与「不能说」不可区分（GitHub 404 惯例），此处仅提示可申请。": "You don't have access—\"don't know\" and \"can't say\" are indistinguishable (the GitHub 404 convention); this page only hints that you can request it.",
 "内容负责人：李四（财务部）": "Content owner: Li Si (Finance)",
 "未申请": "Not requested",
 "点「推进状态机」：未申请 → 已提交（路由明示给内容负责人）→ 已开通（30 天到期倒计时）→ 已过期（中性「可重新申请」）→ 回到未申请": "Click \"Advance state machine\": Not requested → Requested (routing made explicit to the content owner) → Granted (30-day expiry countdown) → Expired (a neutral \"reapply\") → back to Not requested",
 "被拒": "Denied",
 "：被拒五件套——资源名 / 原因 / owner / 申请入口 / 切换身份": ": the five-piece denial kit—resource name / reason / owner / request entry / identity switching",
 "：理由可必填、角色与时长，路由明示「请求将发送给：内容 owner」": ": the reason can be made required, plus role and duration; routing states it plainly—\"request will be sent to: content owner\"",
 "：九态徽章族，idle → requested → granted → expiring → expired → 重交": ": a nine-state badge family—idle → requested → granted → expiring → expired → resubmitted",
 "：  审批方视角——请求卡、批准选权限级、拒绝附留言": ":  the approver's view—request cards, approve with a permission level, reject with a note",
 "到期": "Expiry",
 "：每条 grant 可带  ——永不过期 / 倒计时续期 / 已过期重交": ": every grant can carry  —never expires / renewal countdown / expired and resubmitted",
 "：  返回": ":  returns",
 "denied 不做刺眼红色终态（业界静默默契）；revoked 为审批侧撤销。": "denied never becomes a glaring red terminal state (the industry's quiet convention); revoked means withdrawn by the approver.",
