 "：banner 三态——继承含父链 / 已断继承警示 / 例外 N 项（ ）": ": three banner states—inherited with the parent chain / broken-inheritance warning / N exceptions ( )",
 "主体": "Principals",
 "：授权行五类——user / group / org / anyone / link，组行带成员注记": ": five kinds of grant rows—user / group / org / anyone / link, with member notes on group rows",
