 "为快照渲染；求值语义（先显式 deny → allow 并集 → 默认拒绝）由 kb-core   提供。": "Rendered as a snapshot; evaluation semantics (explicit deny first → union of allows → default deny) come from kb-core   .",
 "上一个：SQL 卡片": "Previous: SQL card",
