 "问数答案 · 组件 · ICEN UI": "Ask-data answers · Components · ICEN UI",
 "点认证徽章 / 图表类型 chips（折线→柱状→饼图）/ 追问 chips / 导出 → 事件与回调双通道回显 · 结果表含截断声明与 null「—」· 权限提示不可关闭（诚实呈现）": "Click the certification badge / chart-type chips (line→bar→pie) / follow-up chips / export → everything echoes through both events and callbacks · the results table carries a truncation notice and renders null as \"—\" · the permission notice cannot be dismissed (honest by design)",
 "认证": "Certification",
 "：  命中可信资产挂徽章，数字本身永远中性": ":  a hit on a trusted asset earns the badge, and the number itself stays neutral",
 "：行级过滤 + 已脱敏列提示，不可关闭（诚实呈现）": ": row-level filtering + notices on already-masked columns, not dismissible (honest by design)",
 "正文": "Body",
 "：  角标流，无效编号降级纯文本": ":  the marker flow; invalid numbers degrade to plain text",
 "结果": "Results",
 "：sticky 表头、null「—」、截断声明、导出": ": sticky table headers, null as \"—\", a truncation notice, and export",
