 "通道 chips 过滤时间线 · 异味行「处置」与「导出 CSV」走事件 · break-glass 行常驻警示（审计粒度 ≥ 常规）": "Channel chips filter the timeline · \"Resolve\" and \"Export CSV\" on smell rows go through events · break-glass rows keep a standing warning (audit granularity ≥ normal)",
 "：通道 chips（全部 / 读取 / 权限变更 / 申请 / 系统）+ 导出 CSV": ": channel chips (All / Read / Permission changes / Requests / System) + export CSV",
 "异味": "Smells",
 "：权限卫生六枚举治理发现，分高 / 中 / 低三级": ": governance findings across six permission-hygiene enums, graded high / medium / low",
 "：actor 三类（human / app / system），读取与预览分列": ": three actor kinds (human / app / system), with reads and previews in separate columns",
 "：应急行常驻警示色 +「实时告警已通知安全团队」": ": emergency rows keep a standing warning color + \"real-time alerts have gone to the security team\"",
 "异味六枚举：过度暴露 / 组织级链接 / 过宽组授权 / 敏感度错配 / 断继承 / 负责人缺位——源系统权限卫生问题，RAG 只是放大器。": "The six smells: over-exposure / org-wide links / over-broad group grants / sensitivity mismatch / broken inheritance / missing owner—permission-hygiene problems rooted in the source system; RAG only amplifies them.",
 "同用户同资源 5 分钟读取去重是数据侧纪律——UI 不重复渲染也不声明条数。": "Deduplicating same-user reads of the same resource within 5 minutes is a data-side discipline—the UI neither renders duplicates nor claims a count.",
