 "双栏工作台 · 组件 · ICEN UI": "Split workspace · Components · ICEN UI",
 "拖中间分隔条调比例（双击复位）· 右栏划选文本浮 AI 工具条 · 底部版本轴点击切换 · 右侧 diff 卡可展开并接受 / 拒绝": "Drag the center divider to rebalance (double-click to reset) · select text in the right pane to float the AI toolbar · click the bottom version rail to switch · the right-side diff card expands to accept / reject",
 "：左对话流 / 右文档各自滚动，宿主内容经   /   挂入": ": the left conversation and right document scroll independently; host content mounts through   /   slots",
