 "工具链条 · 组件 · ICEN UI": "Tool chain · Components · ICEN UI",
 "2.6s 后生成完成、引用核对转 running（幂等重渲不重建 DOM）· 点击已到达步骤派发 icen:kb-chain-step · 未到达步骤置灰不可点": "After 2.6s generation completes and citation checking turns running (idempotent rerender, no DOM rebuild) · clicking a reached step dispatches icen:kb-chain-step · unreached steps are grayed out and unclickable",
 "步骤": "Steps",
 "：检索 → 重排 → 生成 → 引用核对等步骤横向排布": ": steps such as Retrieve → Rerank → Generate → Citation check, laid out horizontally",
 "：四态状态点——pending 空心 / running 脉冲 / done 实心绿 / error 实心红": ": four state dots—pending hollow / running pulsing / done solid green / error solid red",
 "重渲": "Rerender",
 "：幂等重渲只原位更新状态类与文案，不重建 DOM（流式安全无闪烁）": ": idempotent rerenders only update state classes and copy in place, never rebuilding the DOM (streaming-safe, no flicker)",
 "：running / error 及之前步骤可点击 →": ": steps at running / error and earlier are clickable →",
 "与 ai-tool-call 单卡互补；运动感来自动效不来自颜色。": "Complements the single-card ai-tool-call; the sense of motion comes from animation, not color.",
 "上一个：双栏工作台": "Previous: Split workspace",
 "下一个：沙箱工具容器": "Next: Sandbox tool containers",
 "检查点 · 组件 · ICEN UI": "Checkpoint · Components · ICEN UI",
 "点击检查点弹恢复菜单（默认预选「仅内容 · 保留对话」）·「补引用后」scopeOptions 受限：仅 content 可选，其余两项禁用": "Click a checkpoint to open the restore menu ('Content only · keep conversation' preselected by default) · After citation backfill, scopeOptions is limited: only content is selectable and the other two options are disabled",
 "：时钟 icon + 相对时间 + label / reason 的时间轴按钮": ": Timeline button with a clock icon + relative time + label / reason",
 "菜单": "Menu",
 "：  委托点击弹恢复菜单，挂 body、fixed 定位、视口夹取": ":  Delegated clicks open the restore menu, attached to body, fixed-positioned, and clamped to the viewport",
 "范围": "Scope",
 "：scope 三选默认预选「仅内容（保留对话）」（Cursor 语义）": ": Scope offers three choices with 'Content only (keep conversation)' preselected (Cursor semantics)",
 "受限": "Restricted",
 "：  未提供的恢复范围禁用": ":  Restore scopes that aren't provided are disabled",
 "：方向键打开与导航，Home / End 跳首尾；跳过禁用范围，Escape 返回检查点": ": Arrow keys open and navigate the menu, Home / End jump to the ends; disabled scopes are skipped, and Escape returns to the checkpoint",
 "：Tab 离开、外点、文档滚动关闭；菜单复用共享尺寸与浮层材质": ": Tabbing away, clicking outside, or scrolling the document closes it; the menu shares sizing and overlay materials",
 "：选择派发": ": Selection dispatches",
 "默认预选「仅内容」是审计友好语义：回滚产物、保留讨论过程。": "Preselecting 'Content only' by default is audit-friendly: the artifacts roll back while the discussion is kept.",
 "上一个：解析管线": "Previous: Parsing pipeline",
 "下一个：分段策略": "Next: Chunking strategy",
 "分段编辑器 · 组件 · ICEN UI": "Chunk editor · Components · ICEN UI",
 "直接改写正文（失焦提交）/ 点启用开关（第 4 条已停用）/ 敲 Enter 加关键词 / 全文搜索本地过滤（试试「评分」），切「语义」模式只派事件不过滤": "Edit the text in place (commits on blur) / flip the enabled switch (row 4 is disabled) / press Enter to add a keyword / full-text search filters locally (try 'rating'); switching to 'semantic' mode dispatches the event without filtering",
 "：  行内编辑，blur 且变化才提交": ":  Inline editing; commits on blur only when the value changed",
 "：  排除出检索不删除，行降透明": ":  Excluding a row from search doesn't delete it; the row is dimmed",
