 "：chips 域内自实现，× 删除 / Enter 新增": ": The chips field is self-contained: × removes, Enter adds",
 "：全文本地过滤（200ms 防抖）；语义模式交消费方重渲染": ": Full-text filtering is local (200 ms debounce); semantic mode leaves re-rendering to the consumer",
