 "答案正文由 renderCitationText 注入角标 —— 悬停角标 ≥300ms 看引用卡（官方 / 过期 / 受限三种徽标态），点击派事件；末尾 [9] 超出来源数，降级为灰显死角标": "The answer body gets its superscript markers from renderCitationText — hover a marker for ≥300 ms to see the citation card (three badge states: official / stale / restricted); clicking dispatches an event; the trailing [9] exceeds the source count and degrades into a grayed-out dead marker",
 "事件日志：悬停 / 点击任一活角标": "Event log: hover over or click any live marker",
 "：  切「文本节点 + 角标」混合流": ":  Toggles a mixed stream of text nodes + markers",
 "：  写入模块级注册表，hover 卡据此取数": ":  Writes to a module-level registry that the hover card reads from",
 "：hover ≥300ms 经 popover 浮出引用卡": ": Hovering ≥300 ms floats out the citation card via a popover",
 "：类型图标 / 域名 / 引文 ≤150 字 + 官方 / 过期 / 受限徽标": ": Type icon / domain / quote of ≤150 characters + an official / stale / restricted badge",
 "：超界编号自动   灰显不可点": ": Out-of-range numbers are automatically   grayed out and unclickable",
 "：点击派": ": Clicking dispatches",
 "不信任模型生成编号：超界编号一律降级为灰显死角标。": "Never trust model-generated numbering: out-of-range numbers always degrade to grayed-out dead markers.",
