 "：全部接线在 useEffect / onMounted 里，服务端不执行；行为内核本身也有 SSR 守卫（双保险）。": ": all wiring happens in useEffect / onMounted, so nothing executes on the server; the behavior core itself has SSR guards as well (belt and suspenders).",
 "：React StrictMode 会双跑 effect（setup→cleanup→setup），封装层 create/destroy/create 闭环对得上；内核 init 全部幂等，事件不会重复。": ": React StrictMode double-invokes effects (setup→cleanup→setup), which matches the adapters' create/destroy/create loop; the core's init is fully idempotent, so events never fire twice.",
 "opts 比较": "opts comparison",
 "：props.opts 用 JSON.stringify 稳定比较——库内 opts 是纯 JSON 契约；传函数回调（如 columns.render）时 identity 变化不影响，内容变化请换引用。": ": props.opts is compared stably via JSON.stringify — opts are a pure JSON contract inside the library. Function callbacks (e.g. columns.render) are unaffected by identity changes; when the contents change, pass a new reference.",
 "事件广播": "Event broadcasting",
