 "上一季度各区域毛利率": "Last quarter's gross margin by region",
 "导出钮在宿主未接 onExport 回调时保持禁用——不给假按钮；「已截断：显示 5/31 行」是契约声明，不是瑕疵。": "The export button stays disabled until the host wires up onExport — no fake buttons; \"Truncated: showing 5/31 rows\" is a contract statement, not a flaw.",
 "kb-sql · 着色 + 修正 diff + 编辑重跑": "kb-sql · syntax highlighting + correction diff + edit and rerun",
 "kb-trace · 一次完整问答的 span 树（展开检索看命中）": "kb-trace · the span tree of one full Q&A (expand the retrieval step to see the hits)",
 "kb-review · 键盘可用（←/→ 切条目 · 1–9 打分 · ⌘↵ 提交 · ? 帮助）": "kb-review · keyboard-ready (←/→ switch items · 1–9 score · ⌘↵ submit · ? help)",
