 [`所有 ${META.components} 个组件共享同一套抽象：`]: `All ${META.components} components share the same set of abstractions:`,
 "（HTML 显式组合）与": " (explicit HTML composition) and ",
 "原语变量层": "primitive variable layer",
 "（CSS 自洽消费）。换原语只需覆盖少数变量，全局组件自动换肤。": " (self-contained CSS consumption). Switching primitives only overrides a few of these variables, and every component reskins automatically.",
 "：连续几何、轻盈材料、系统排版。": ": continuous geometry, lightweight materials, systematic typography.",
 "：宋式器物、纤细边线、书卷排版与疏朗留白。": ": Song-dynasty wares, hairline borders, bookish typography, and airy whitespace.",
