 "选择一组，整页随之切换。标题、输入、按钮与浮层使用同一套规则；之后仍可在顶栏单独换主题。": "Pick one and the whole page switches with it. Headings, inputs, buttons, and overlays follow the same rules; you can still change the theme separately from the top bar later.",
