 "6 个交互基元": "Six interaction primitives",
 "下方演示直接挂原语 class（不带任何组件 class），可见其承载的最小可识别交互：": "The demos below attach primitive classes directly (no component classes at all), so you can see the smallest recognizable interaction each one carries:",
 "可按压基元：hover 顶部高光、focus-visible 双层环、active 下陷、aria-busy 减淡、disabled 50% 透明。": "Pressable primitive: hover top highlight, focus-visible double ring, active press-down, aria-busy dimming, disabled at 50% opacity.",
 "表单控件 wrapper：hover 边框过渡、focus-within 内嵌阴影 + accent 3px 光晕、:invalid 错误态自动接管。": "Form-control wrapper: hover border transition, focus-within inset shadow + a 3px accent glow, and the :invalid error state taking over automatically.",
