 "主题 · ICEN UI": "Themes · ICEN UI",
 "6 套主题，各带明暗双模，每套都定义完整的   色彩面。组件只消费 token——换肤不改一行组件代码。在导航栏切换预设与明暗，本页色板实时跟随。": "Six themes, each with light and dark modes, and each defining a complete   color surface. Components consume tokens only — reskinning never touches a line of component code. Switch presets and color modes in the nav bar, and the swatches on this page follow in real time.",
 "瓷白与冷蓝，让内容清楚，让操作轻盈。": "Porcelain white and cool blue keep content clear and controls light.",
 "清透瓷面 · 冷调柔光": "Clear porcelain · cool, soft light",
 "绢白留出呼吸，青瓷与沉墨相映，温润而有分寸。": "Silk white leaves room to breathe, celadon plays against deep ink — warm, restrained, and well-measured.",
 "绢本与青瓷 · 温润细光": "Silk and celadon · warm, fine light",
 "石灰白、铁灰与深朱红，以清楚的结构托住有分量的内容。": "Limestone white, iron gray, and deep vermilion hold weighty content on a clear structure.",
 "混凝土与搪瓷 · 实体承重": "Concrete and enamel · solid support",
 "象牙白与乌木黑保持主次，金棕只落在关键动作。": "Ivory white and ebony black keep the hierarchy; golden brown lands only on key actions.",
 "象牙琴键 · 乌木与漆面微光": "Ivory keys · ebony and a lacquer gleam",
 "水面蓝绿叠出柔光，紫调含蓄，安静而不寡淡。": "Blue-greens layer into soft light on the water; the purple stays understated — quiet, never bland.",
 "睡莲水面 · 蓝绿柔光与含蓄紫调": "Water-lily surface · blue-green soft light with restrained purple",
 "日间是麦田里的钴蓝，入夜是深蓝上的星光金。": "By day, cobalt blue in the wheat fields; by night, starlight gold on deep blue.",
 "亚麻画布 · 钴蓝与麦穗金": "Linen canvas · cobalt and wheat gold",
 "tokens 同时导出为设计工具互操作格式（DTCG 经典版 → Tokens Studio / Figma Variables），设计侧改 token 可走插件回灌，闭环到  。": "Tokens are also exported as design-tool interchange formats (classic DTCG → Tokens Studio / Figma Variables); designers can edit tokens and push them back through the plugins, closing the loop at  .",
