 "新供应商准入需提交五类材料：营业执照副本、近两年审计报告、质量体系认证（ISO 9001 或同等）、样品检测报告与环保合规声明": "New suppliers must submit five categories of documents: a business license copy, audited financial reports for the past two years, quality system certification (ISO 9001 or equivalent), sample test reports, and an environmental compliance declaration",
