 "查看分段（3）": "View chunks (3)",
 "供应商准入材料清单。营业执照副本、近两年审计报告、质量体系认证、样品检测报告。": "Supplier onboarding document list. Business license copy, audited reports for the past two years, quality system certification, sample test reports.",
 "办理入口： vendor@icen.ai。\n资质初审 5 个工作日；现场审核仅 A/B 级候选必做；评分 ≥ 85 为 A 级，账期 60 天。": "How to apply: vendor@icen.ai.\nQualification review takes 5 business days; on-site audits are required only for Tier A/B candidates; a score of 85 or higher is Tier A, with 60-day payment terms.",
 "复审规则：连续两个季度评分下滑触发复审；复审材料与首次准入一致。": "Re-review rules: score declines in two consecutive quarters trigger a re-review; the documents required are the same as for initial onboarding.",
 "新供应商申请准入需提交以下材料：营业执照副本、近两年审计报告、质量体系认证（ISO 9001 或同等）、样品检测报告，以及环保合规声明。": "New suppliers applying for onboarding must submit the following: a business license copy, audited financial reports for the past two years, quality system certification (ISO 9001 or equivalent), sample test reports, and an environmental compliance declaration.",
 "准入": "Onboarding",
 "材料清单": "Document list",
 "流程依次为：在线提交申请 → 资质初审（5 个工作日）→ 现场审核（A/B 级候选必做）→ 供应商分级评定 → 签署框架协议。": "The process runs: submit the application online → qualification review (5 business days) → on-site audit (required for Tier A/B candidates) → supplier tier rating → framework agreement signing.",
 "流程": "Process",
 "初审": "Initial review",
 "综合评分 ≥ 85 为 A 级，70–84 为 B 级，60–69 为 C 级。付款账期：A 级 60 天、B 级 45 天、C 级 30 天。": "A composite score of 85 or higher is Tier A, 70–84 is Tier B, and 60–69 is Tier C. Payment terms: 60 days for Tier A, 45 days for Tier B, 30 days for Tier C.",
 "分级": "Tiering",
 "账期": "Payment terms",
 "（历史条款）2019 版要求全部供应商每年线下报备年检材料，已于 v4.0 废止。": "(Historical clause) The 2019 edition required all suppliers to file annual inspection documents offline every year; rescinded in v4.0.",
 "废止": "Rescinded",
 "各区域毛利率：华东 34.2%、华南 31.8%、华北 28.6%、西南 22.4%、东北 26.9%。": "Gross margin by region: East China 34.2%, South China 31.8%, North China 28.6%, Southwest 22.4%, Northeast 26.9%.",
 "毛利率": "Gross margin",
 "毛利率 =（营业收入 − 营业成本）/ 营业收入，全量按不含税口径统计；区域归属以客户主体注册地为准。": "Gross margin = (operating revenue − operating cost) / operating revenue, measured tax-exclusive across the board; regions are assigned by each customer entity's place of registration.",
 "不含税": "Tax-exclusive",
 "数据分四级：L1 公开、L2 内部、L3 机密、L4 核心机密。客户联系方式、合同金额属 L3。": "Data falls into four levels: L1 public, L2 internal, L3 confidential, L4 top secret. Customer contact details and contract amounts are L3.",
 "2026 Q3 季度经营复盘 · 第 2 页": "2026 Q3 Business Review · Page 2",
 "各区域": "By region",
 "：华东 34.2%、华南 31.8%、华北 28.6%、西南 22.4%、东北 26.9%。环比：华东 +1.2pct、西南 -1.1pct。": ": East China 34.2%, South China 31.8%, North China 28.6%, Southwest 22.4%, Northeast 26.9%. QoQ: East China +1.2pct, Southwest -1.1pct.",
