 "2026 Q3 季度经营复盘 · 第 3 页": "2026 Q3 Business Review · Page 3",
 "=（营业收入 − 营业成本）/ 营业收入，全量按不含税口径统计；区域归属以客户主体注册地为准。Q4 华南区供应链降本 3pct。": "= (operating revenue − operating cost) / operating revenue, measured tax-exclusive across the board; regions are assigned by each customer entity's place of registration. Q4 supply chain costs in South China down 3pct.",
 "供应商准入手册 v4.2 · 第 3 页": "Supplier Onboarding Manual v4.2 · Page 3",
 "流程依次为：在线提交申请 → 资质初审（5 个工作日）→ 现场审核（A/B 级候选必做）→ 供应商分级评定 → 签署框架协议。全流程": "The process runs: submit the application online → qualification review (5 business days) → on-site audit (required for Tier A/B candidates) → supplier tier rating → framework agreement signing. The full process",
